// eslint-disable-next-line import/no-webpack-loader-syntax
import PredictionWorker from "worker-loader!./orbitPrediction.worker";
import {predictTrajectory} from "./orbitPhysics";

export default function createPredictor() {
  let worker;
  try {
    if (typeof Worker !== "undefined") worker = new PredictionWorker();
  } catch (error) {
    /* Fallback for browsers that disable workers. */
  }
  let latestId = 0,
    active = false,
    pending = null,
    disposed = false,
    timer;
  const finish = data => {
    active = false;
    if (disposed) return;
    if (data.id === latestId && pending === null) current.callback(data.paths);
    pump();
  };
  let current;
  const pump = () => {
    if (disposed || active || !pending) return;
    current = pending;
    pending = null;
    active = true;
    const {callback, ...request} = current;
    if (worker) worker.postMessage(request);
    else
      timer = setTimeout(() => {
        let paths;
        try {
          paths = predictTrajectory(
            request.world,
            request.craft,
            request.options
          );
          paths.source = "fallback";
        } catch (error) {
          paths = {current: [], maneuver: [], predictionError: error.message};
        }
        finish({id: request.id, paths});
      }, 0);
  };
  if (worker) {
    worker.onmessage = event => finish(event.data);
    worker.onerror = () => {
      worker.terminate();
      worker = null;
      active = false;
      if (!pending) pending = current;
      pump();
    };
  }
  return {
    request(world, craft, options, callback) {
      if (disposed) return;
      latestId += 1;
      // A pending request is immutable and supersedes older slider positions.
      pending = {
        id: latestId,
        world: {
          time: world.time,
          drag: world.drag,
          perturbations: world.perturbations
        },
        craft: {
          ...craft,
          position: craft.position.slice(),
          velocity: craft.velocity.slice(),
          trail: []
        },
        options,
        callback
      };
      pump();
    },
    dispose() {
      disposed = true;
      pending = null;
      clearTimeout(timer);
      if (worker) worker.terminate();
    }
  };
}
