import React, {useEffect, useRef, useState} from "react";
import * as THREE from "three";
import {OrbitControls} from "three/examples/jsm/controls/OrbitControls";
import {
  PLANET,
  MOON,
  moonPosition,
  directionVector,
  gravityAcceleration
} from "./orbitPhysics";
import "./OrbitScene.scss";

// The renderer uses 1 scene unit = 1,000 km. Physics always stays in km and seconds.
const SCALE = 1 / 1000;
const SUN = new THREE.Vector3(-1, -0.75, 0.55).normalize();
const NORTH = new THREE.Vector3(0, 0, 1);
const toScene = value =>
  new THREE.Vector3(value[0], value[1], value[2]).multiplyScalar(SCALE);
const positionOf = point => (Array.isArray(point) ? point : point.position);

function seeded(seed) {
  let value = seed;
  return () => {
    value = (value * 1664525 + 1013904223) >>> 0;
    return value / 4294967296;
  };
}

function earthTextures(renderer) {
  const loader = new THREE.TextureLoader();
  const base = `${process.env.PUBLIC_URL || ""}/orbit-textures/`;
  const anisotropy = Math.min(8, renderer.capabilities.getMaxAnisotropy());
  const load = (name, color = false) => {
    const texture = loader.load(base + name);
    texture.wrapS = THREE.RepeatWrapping;
    texture.anisotropy = anisotropy;
    texture.encoding = color ? THREE.sRGBEncoding : THREE.LinearEncoding;
    return texture;
  };
  return [
    load("earth-day.jpg", true),
    load("earth-specular.png"),
    load("earth-night.jpg"),
    load("earth-clouds.jpg")
  ];
}
function moonTexture() {
  const canvas = document.createElement("canvas");
  canvas.width = 512;
  canvas.height = 256;
  const context = canvas.getContext("2d"),
    random = seeded(37);
  context.fillStyle = "#9b9c96";
  context.fillRect(0, 0, 512, 256);
  for (let i = 0; i < 850; i++) {
    const x = random() * 512,
      y = random() * 256,
      radius = 1 + Math.pow(random(), 3) * 25;
    const gradient = context.createRadialGradient(
      x - radius * 0.2,
      y - radius * 0.2,
      0,
      x,
      y,
      radius
    );
    gradient.addColorStop(0, "rgba(41,45,46,.45)");
    gradient.addColorStop(0.65, "rgba(61,64,64,.25)");
    gradient.addColorStop(0.82, "rgba(220,220,207,.22)");
    gradient.addColorStop(1, "rgba(150,150,146,0)");
    context.fillStyle = gradient;
    context.beginPath();
    context.arc(x, y, radius, 0, Math.PI * 2);
    context.fill();
  }
  return new THREE.CanvasTexture(canvas);
}

function eclipseMaterial(material, occluderRadius) {
  const uniforms = {
    eclipseBody: {value: new THREE.Vector3()},
    eclipseRadius: {value: occluderRadius},
    eclipseSun: {value: SUN}
  };
  material.onBeforeCompile = shader => {
    Object.assign(shader.uniforms, uniforms);
    shader.vertexShader = "varying vec3 eclipseWorld;\n" + shader.vertexShader;
    shader.vertexShader = shader.vertexShader.replace(
      "#include <project_vertex>",
      "#include <project_vertex>\neclipseWorld = (modelMatrix * vec4(transformed, 1.0)).xyz;"
    );
    shader.fragmentShader =
      "varying vec3 eclipseWorld; uniform vec3 eclipseBody; uniform float eclipseRadius; uniform vec3 eclipseSun;\n" +
      shader.fragmentShader;
    shader.fragmentShader = shader.fragmentShader.replace(
      "#include <dithering_fragment>",
      `
      vec3 eclipseOffset = eclipseBody - eclipseWorld;
      float eclipseAlong = dot(eclipseOffset, eclipseSun);
      float eclipseDistance = length(eclipseOffset - eclipseSun * eclipseAlong);
      float eclipse = (1.0 - smoothstep(eclipseRadius * 0.94, eclipseRadius * 1.07, eclipseDistance)) * step(0.0, eclipseAlong);
      gl_FragColor.rgb *= 1.0 - eclipse * 0.93;
      #include <dithering_fragment>`
    );
  };
  return uniforms;
}

function makeSpacecraft() {
  const group = new THREE.Group();
  const gold = new THREE.MeshPhongMaterial({color: 0xcfb47d, shininess: 45});
  const blue = new THREE.MeshPhongMaterial({
    color: 0x174e73,
    shininess: 78,
    specular: 0x76cbdd,
    side: THREE.DoubleSide
  });
  const silver = new THREE.MeshPhongMaterial({color: 0xb9c6cd, shininess: 70});
  const body = new THREE.Mesh(new THREE.BoxGeometry(0.23, 0.4, 0.23), gold);
  group.add(body);
  const antenna = new THREE.Mesh(
    new THREE.CylinderGeometry(0.016, 0.016, 0.28, 6),
    silver
  );
  antenna.position.y = 0.33;
  group.add(antenna);
  const dish = new THREE.Mesh(
    new THREE.SphereGeometry(0.105, 12, 6, 0, Math.PI * 2, 0, Math.PI * 0.5),
    silver
  );
  dish.position.set(0, 0.47, 0);
  group.add(dish);
  [-1, 1].forEach(side => {
    const panel = new THREE.Mesh(
      new THREE.BoxGeometry(0.48, 0.55, 0.012),
      blue
    );
    panel.position.x = side * 0.4;
    group.add(panel);
    for (let i = 0; i < 4; i++) {
      const line = new THREE.Mesh(
        new THREE.BoxGeometry(0.005, 0.55, 0.017),
        silver
      );
      line.position.set(side * 0.4 + (i - 1.5) * 0.11, 0, 0);
      group.add(line);
    }
    const spar = new THREE.Mesh(
      new THREE.BoxGeometry(0.25, 0.018, 0.018),
      silver
    );
    spar.position.x = side * 0.2;
    group.add(spar);
  });
  const nozzle = new THREE.Mesh(
    new THREE.CylinderGeometry(0.052, 0.085, 0.14, 10),
    silver
  );
  nozzle.position.y = -0.26;
  group.add(nozzle);
  const plume = new THREE.Group();
  const fire = new THREE.Mesh(
    new THREE.ConeGeometry(0.078, 0.75, 16, 1, true),
    new THREE.MeshBasicMaterial({
      color: 0x52c7f5,
      transparent: true,
      opacity: 0.55,
      blending: THREE.AdditiveBlending,
      side: THREE.DoubleSide,
      depthWrite: false
    })
  );
  fire.position.y = -0.7;
  plume.add(fire);
  const core = new THREE.Mesh(
    new THREE.ConeGeometry(0.042, 0.47, 12),
    new THREE.MeshBasicMaterial({
      color: 0xe5faff,
      transparent: true,
      opacity: 0.9,
      blending: THREE.AdditiveBlending,
      depthWrite: false
    })
  );
  core.position.y = -0.56;
  plume.add(core);
  group.add(plume);
  plume.visible = false;
  const marker = new THREE.Mesh(
    new THREE.RingGeometry(1, 1.025, 48),
    new THREE.MeshBasicMaterial({
      color: 0x7be4e9,
      side: THREE.DoubleSide,
      transparent: true,
      opacity: 0.65,
      depthWrite: false
    })
  );
  const velocity = new THREE.ArrowHelper(
    new THREE.Vector3(0, 1, 0),
    new THREE.Vector3(),
    1,
    0x70d7e6,
    0.15,
    0.07
  );
  const gravity = new THREE.ArrowHelper(
    new THREE.Vector3(-1, 0, 0),
    new THREE.Vector3(),
    1,
    0xe8b974,
    0.15,
    0.07
  );
  const trail = new THREE.Line(
    new THREE.BufferGeometry(),
    new THREE.LineBasicMaterial({
      color: 0x57b3c3,
      transparent: true,
      opacity: 0.58
    })
  );
  return {group, marker, plume, velocity, gravity, trail};
}

function replaceLine(line, points) {
  const vertices = [];
  (points || []).forEach(point => {
    const position = positionOf(point);
    if (position && position.every(Number.isFinite))
      vertices.push(
        position[0] * SCALE,
        position[1] * SCALE,
        position[2] * SCALE
      );
  });
  line.geometry.dispose();
  line.geometry = new THREE.BufferGeometry();
  line.geometry.setAttribute(
    "position",
    new THREE.Float32BufferAttribute(vertices, 3)
  );
  if (line.isLine && line.material.isLineDashedMaterial)
    line.computeLineDistances();
}

export default function OrbitScene(props) {
  const hostRef = useRef(null),
    latestRef = useRef(props),
    engineRef = useRef(null);
  const [labels, setLabels] = useState([]);
  const [ready, setReady] = useState(false);
  const [draggingNode, setDraggingNode] = useState(false);
  latestRef.current = props;

  useEffect(() => {
    const host = hostRef.current;
    let renderer;
    try {
      renderer = new THREE.WebGLRenderer({
        antialias: true,
        alpha: false,
        powerPreference: "high-performance"
      });
    } catch (error) {
      if (latestRef.current.onRendererError)
        latestRef.current.onRendererError(
          "This browser could not start WebGL. Try enabling hardware acceleration or opening Orbit Playground in another browser. Simulation controls remain available."
        );
      return undefined;
    }
    renderer.outputEncoding = THREE.sRGBEncoding;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.05;
    renderer.setClearColor(0x03060b);
    renderer.domElement.setAttribute(
      "aria-label",
      "Interactive orbital scene. Drag to orbit the camera, scroll or pinch to zoom, select a spacecraft, or drag the amber maneuver marker to move a planned burn."
    );
    renderer.domElement.setAttribute("role", "img");
    host.appendChild(renderer.domElement);
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(42, 1, 0.001, 200000);
    camera.up.copy(NORTH);
    camera.position.set(16, -23, 13);
    const controls = new OrbitControls(camera, renderer.domElement);
    const reduced =
      window.matchMedia &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    controls.enableDamping = !reduced;
    controls.dampingFactor = 0.065;
    controls.minDistance = 0.025;
    controls.maxDistance = 100000;
    controls.zoomSpeed = 0.8;
    controls.rotateSpeed = 0.65;
    controls.screenSpacePanning = true;
    controls.enableKeys = false;
    const sunlight = new THREE.DirectionalLight(0xfffaf2, 1.6);
    sunlight.position.copy(SUN).multiplyScalar(1000);
    scene.add(sunlight);
    scene.add(new THREE.AmbientLight(0x8ea8d1, 0.035));
    const [map, specularMap, cityMap, cloudMap] = earthTextures(renderer);
    map.encoding = THREE.sRGBEncoding;
    const planetGeometry = new THREE.SphereGeometry(
      PLANET.radius * SCALE,
      96,
      64
    );
    const planetMaterial = new THREE.MeshStandardMaterial({
      map,
      roughness: 0.85,
      metalness: 0
    });
    const planetEclipse = eclipseMaterial(planetMaterial, MOON.radius * SCALE);
    const compileSurface = planetMaterial.onBeforeCompile;
    planetMaterial.onBeforeCompile = shader => {
      compileSurface(shader);
      shader.uniforms.oceanMask = {value: specularMap};
      shader.fragmentShader =
        "uniform sampler2D oceanMask;\n" + shader.fragmentShader;
      shader.fragmentShader = shader.fragmentShader.replace(
        "#include <roughnessmap_fragment>",
        "#include <roughnessmap_fragment>\nroughnessFactor = mix(0.95, 0.48, texture2D(oceanMask, vUv).r);"
      );
      // A small sunlit blue scattering contribution gives the oceans their
      // appearance from orbit; the outer shell supplies the thin limb glow.
      shader.fragmentShader = shader.fragmentShader.replace(
        "#include <emissivemap_fragment>",
        `#include <emissivemap_fragment>
         vec3 surfaceNormal = normalize(eclipseWorld);
         float surfaceDay = smoothstep(-0.08, 0.3, dot(surfaceNormal, eclipseSun));
         float surfaceLimb = pow(1.0 - abs(dot(surfaceNormal, normalize(cameraPosition - eclipseWorld))), 2.0);
         totalEmissiveRadiance += vec3(0.002, 0.009, 0.022) * surfaceDay * (0.4 + 0.6 * surfaceLimb);`
      );
    };
    const planet = new THREE.Mesh(planetGeometry, planetMaterial);
    planet.rotation.x = Math.PI * 0.5;
    planet.rotation.y = -0.45;
    scene.add(planet);
    const clouds = new THREE.Mesh(
      new THREE.SphereGeometry((PLANET.radius + 10) * SCALE, 72, 48),
      new THREE.MeshPhongMaterial({
        color: 0xffffff,
        alphaMap: cloudMap,
        transparent: true,
        opacity: 0.92,
        depthWrite: false,
        shininess: 0
      })
    );
    clouds.rotation.copy(planet.rotation);
    scene.add(clouds);
    const atmosphere = new THREE.Mesh(
      new THREE.SphereGeometry((PLANET.radius + 70) * SCALE, 80, 48),
      new THREE.ShaderMaterial({
        uniforms: {sunDirection: {value: SUN}},
        transparent: true,
        depthWrite: false,
        side: THREE.BackSide,
        blending: THREE.AdditiveBlending,
        vertexShader:
          "varying vec3 worldNormal; varying vec3 worldPoint; void main(){ worldNormal = normalize(mat3(modelMatrix) * normal); worldPoint = (modelMatrix * vec4(position,1.0)).xyz; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }",
        fragmentShader:
          "uniform vec3 sunDirection; varying vec3 worldNormal; varying vec3 worldPoint; void main(){ vec3 eye=normalize(cameraPosition-worldPoint); float rim=pow(max(0.0,1.0-abs(dot(normalize(worldNormal),eye))),4.0); float daylight=smoothstep(-0.25,0.65,dot(normalize(worldNormal),sunDirection)); vec3 blue=mix(vec3(0.06,0.17,0.32),vec3(0.20,0.59,0.92),daylight); gl_FragColor=vec4(blue,rim*(0.2+daylight*0.8)); }"
      })
    );
    scene.add(atmosphere);
    const cities = new THREE.Mesh(
      new THREE.SphereGeometry(PLANET.radius * SCALE * 1.001, 72, 48),
      new THREE.ShaderMaterial({
        uniforms: {cityMap: {value: cityMap}, sunDirection: {value: SUN}},
        transparent: true,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        vertexShader:
          "varying vec2 cityUv; varying vec3 worldNormal; void main(){cityUv=uv; worldNormal=normalize(mat3(modelMatrix)*normal); gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}",
        fragmentShader:
          "uniform sampler2D cityMap; uniform vec3 sunDirection; varying vec2 cityUv; varying vec3 worldNormal; void main(){vec3 lights=texture2D(cityMap,cityUv).rgb;float night=1.0-smoothstep(-0.3,0.05,dot(normalize(worldNormal),sunDirection));gl_FragColor=vec4(lights*night*0.8,night*0.65);}"
      })
    );
    cities.rotation.copy(planet.rotation);
    scene.add(cities);
    const moonMap = moonTexture();
    moonMap.encoding = THREE.sRGBEncoding;
    const moonMaterial = new THREE.MeshPhongMaterial({
      map: moonMap,
      bumpMap: moonMap,
      bumpScale: 0.028,
      shininess: 2
    });
    const moonEclipse = eclipseMaterial(moonMaterial, PLANET.radius * SCALE);
    const moon = new THREE.Mesh(
      new THREE.SphereGeometry(MOON.radius * SCALE, 64, 40),
      moonMaterial
    );
    moon.rotation.x = Math.PI * 0.5;
    scene.add(moon);
    moonEclipse.eclipseBody.value.set(0, 0, 0);
    const starRandom = seeded(927),
      starPositions = [];
    for (let i = 0; i < 4200; i++) {
      const phi = starRandom() * Math.PI * 2,
        cosine = starRandom() * 2 - 1,
        sine = Math.sqrt(1 - cosine * cosine);
      const distance = 6000 + starRandom() * 3000;
      starPositions.push(
        Math.cos(phi) * sine * distance,
        Math.sin(phi) * sine * distance,
        cosine * distance
      );
    }
    const starsGeometry = new THREE.BufferGeometry();
    starsGeometry.setAttribute(
      "position",
      new THREE.Float32BufferAttribute(starPositions, 3)
    );
    const stars = new THREE.Points(
      starsGeometry,
      new THREE.PointsMaterial({
        color: 0x93a9c7,
        size: 0.85,
        sizeAttenuation: false,
        transparent: true,
        opacity: 0.7,
        depthWrite: false
      })
    );
    scene.add(stars);
    const sun = new THREE.Mesh(
      new THREE.SphereGeometry(25, 32, 20),
      new THREE.MeshBasicMaterial({color: 0xffefd1})
    );
    sun.position.copy(SUN).multiplyScalar(2800);
    scene.add(sun);
    const sunGlow = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: (() => {
          const canvas = document.createElement("canvas");
          canvas.width = 128;
          canvas.height = 128;
          const context = canvas.getContext("2d"),
            gradient = context.createRadialGradient(64, 64, 3, 64, 64, 64);
          gradient.addColorStop(0, "rgba(255,241,201,.85)");
          gradient.addColorStop(0.2, "rgba(255,216,145,.28)");
          gradient.addColorStop(1, "rgba(255,210,123,0)");
          context.fillStyle = gradient;
          context.fillRect(0, 0, 128, 128);
          return new THREE.CanvasTexture(canvas);
        })(),
        color: 0xffffff,
        blending: THREE.AdditiveBlending,
        depthWrite: false
      })
    );
    sunGlow.position.copy(sun.position);
    sunGlow.scale.set(250, 250, 1);
    scene.add(sunGlow);
    const plane = new THREE.Group();
    [7, 10, 15, 25, 50, 100, MOON.distance * SCALE].forEach(radius => {
      const points = [];
      for (let i = 0; i <= 128; i++)
        points.push(
          new THREE.Vector3(
            radius * Math.cos((i / 128) * Math.PI * 2),
            radius * Math.sin((i / 128) * Math.PI * 2),
            0
          )
        );
      plane.add(
        new THREE.Line(
          new THREE.BufferGeometry().setFromPoints(points),
          new THREE.LineBasicMaterial({
            color: 0x44758b,
            transparent: true,
            opacity: 0.22
          })
        )
      );
    });
    for (let angle = 0; angle < Math.PI; angle += Math.PI / 4) {
      plane.add(
        new THREE.Line(
          new THREE.BufferGeometry().setFromPoints([
            new THREE.Vector3(
              -400 * Math.cos(angle),
              -400 * Math.sin(angle),
              0
            ),
            new THREE.Vector3(400 * Math.cos(angle), 400 * Math.sin(angle), 0)
          ]),
          new THREE.LineBasicMaterial({
            color: 0x44758b,
            transparent: true,
            opacity: 0.13
          })
        )
      );
    }
    scene.add(plane);
    const currentLine = new THREE.Line(
      new THREE.BufferGeometry(),
      new THREE.LineBasicMaterial({
        color: 0x9bced6,
        transparent: true,
        opacity: 0.57
      })
    );
    const maneuverLine = new THREE.Line(
      new THREE.BufferGeometry(),
      new THREE.LineDashedMaterial({
        color: 0xffbd6c,
        transparent: true,
        opacity: 0.85,
        dashSize: 0.18,
        gapSize: 0.1
      })
    );
    scene.add(currentLine, maneuverLine);
    const nodeMarker = new THREE.Mesh(
      new THREE.OctahedronGeometry(1, 0),
      new THREE.MeshBasicMaterial({
        color: 0xffc77e,
        transparent: true,
        opacity: 0.95
      })
    );
    scene.add(nodeMarker);
    const craftMeshes = new Map();
    const pointer = new THREE.Vector2(),
      raycaster = new THREE.Raycaster();
    const size = {width: 1, height: 1};
    const engine = {renderer, scene, camera, controls};
    engineRef.current = engine;
    let frame,
      disposed = false,
      lastLabels = 0,
      lastTrails = 0,
      lastPaths,
      lastSelected,
      lastMode,
      lastTarget,
      lastCameraRevision,
      tween = null,
      previousFollow = null,
      pointerDown = null,
      movingNode = false,
      quality;
    const resize = () => {
      size.width = Math.max(1, host.clientWidth);
      size.height = Math.max(1, host.clientHeight);
      renderer.setSize(size.width, size.height, false);
      camera.aspect = size.width / size.height;
      camera.updateProjectionMatrix();
    };
    const observer =
      typeof ResizeObserver !== "undefined" ? new ResizeObserver(resize) : null;
    if (observer) observer.observe(host);
    window.addEventListener("resize", resize);
    resize();
    const projected = point => {
      const relative = point.clone().sub(camera.position);
      const forward = camera.getWorldDirection(new THREE.Vector3());
      if (relative.dot(forward) <= 0) return null;
      const p = point.clone().project(camera);
      if (p.z < -1 || p.z > 1 || Math.abs(p.x) > 1 || Math.abs(p.y) > 1)
        return null;
      return {
        x: ((p.x + 1) * size.width) / 2,
        y: ((1 - p.y) * size.height) / 2
      };
    };
    const aimPointer = event => {
      const bounds = renderer.domElement.getBoundingClientRect();
      pointer.set(
        ((event.clientX - bounds.left) / bounds.width) * 2 - 1,
        (-(event.clientY - bounds.top) / bounds.height) * 2 + 1
      );
      raycaster.setFromCamera(pointer, camera);
      return {x: event.clientX - bounds.left, y: event.clientY - bounds.top};
    };
    const nodeMove = event => {
      if (!movingNode) return;
      const cursor = aimPointer(event),
        path = latestRef.current.paths && latestRef.current.paths.current;
      const world = latestRef.current.worldRef.current;
      if (!path || !world) return;
      let closest = Infinity,
        chosen;
      path.forEach(point => {
        const projectedPoint = projected(toScene(positionOf(point)));
        if (!projectedPoint) return;
        const distance =
          Math.pow(projectedPoint.x - cursor.x, 2) +
          Math.pow(projectedPoint.y - cursor.y, 2);
        if (distance < closest) {
          closest = distance;
          chosen = point;
        }
      });
      if (chosen && latestRef.current.onNodeTimeChange)
        latestRef.current.onNodeTimeChange(
          Math.max(0, chosen.time - world.time)
        );
      event.preventDefault();
    };
    const onPointerDown = event => {
      aimPointer(event);
      pointerDown = {x: event.clientX, y: event.clientY};
      if (nodeMarker.visible && raycaster.intersectObject(nodeMarker).length) {
        movingNode = true;
        controls.enabled = false;
        setDraggingNode(true);
        renderer.domElement.setPointerCapture(event.pointerId);
        event.preventDefault();
        event.stopPropagation();
      }
    };
    const onPointerUp = event => {
      if (movingNode) {
        movingNode = false;
        controls.enabled = true;
        setDraggingNode(false);
        pointerDown = null;
        return;
      }
      if (
        !pointerDown ||
        Math.hypot(
          event.clientX - pointerDown.x,
          event.clientY - pointerDown.y
        ) > 7
      ) {
        pointerDown = null;
        return;
      }
      aimPointer(event);
      let closest = Infinity,
        selected;
      craftMeshes.forEach((meshes, id) => {
        const sphere = new THREE.Sphere(
          meshes.group.position,
          meshes.group.scale.x * 1.2
        );
        const hit = raycaster.ray.intersectSphere(sphere, new THREE.Vector3());
        if (hit && hit.distanceTo(camera.position) < closest) {
          closest = hit.distanceTo(camera.position);
          selected = id;
        }
      });
      if (selected && latestRef.current.onSelect)
        latestRef.current.onSelect(selected);
      pointerDown = null;
    };
    const onPointerCancel = () => {
      movingNode = false;
      controls.enabled = true;
      setDraggingNode(false);
      pointerDown = null;
    };
    const onContextLost = event => {
      event.preventDefault();
      if (latestRef.current.onRendererError)
        latestRef.current.onRendererError(
          "The graphics context was interrupted. Reload this page to restore the 3D view; your saved scenarios remain available."
        );
    };
    const onKey = event => {
      if (
        ![
          "ArrowLeft",
          "ArrowRight",
          "ArrowUp",
          "ArrowDown",
          "+",
          "=",
          "-"
        ].includes(event.key)
      )
        return;
      event.preventDefault();
      const offset = camera.position.clone().sub(controls.target);
      if (event.key === "+" || event.key === "=") offset.multiplyScalar(0.9);
      else if (event.key === "-") offset.multiplyScalar(1.1);
      else if (event.key === "ArrowLeft" || event.key === "ArrowRight")
        offset.applyAxisAngle(NORTH, event.key === "ArrowLeft" ? -0.08 : 0.08);
      else
        offset.applyAxisAngle(
          camera
            .getWorldDirection(new THREE.Vector3())
            .cross(NORTH)
            .normalize(),
          event.key === "ArrowUp" ? -0.08 : 0.08
        );
      camera.position.copy(controls.target).add(offset);
      controls.update();
    };
    renderer.domElement.tabIndex = 0;
    renderer.domElement.addEventListener("pointerdown", onPointerDown, true);
    renderer.domElement.addEventListener("pointermove", nodeMove, true);
    renderer.domElement.addEventListener("pointerup", onPointerUp, true);
    renderer.domElement.addEventListener("pointercancel", onPointerCancel);
    renderer.domElement.addEventListener("webglcontextlost", onContextLost);
    renderer.domElement.addEventListener("keydown", onKey);
    const disposeObject = object => {
      object.traverse(child => {
        if (child.geometry) child.geometry.dispose();
        if (child.material)
          (Array.isArray(child.material)
            ? child.material
            : [child.material]
          ).forEach(material => material.dispose());
      });
    };
    const animate = timestamp => {
      if (disposed) return;
      const p = latestRef.current,
        world = p.worldRef.current;
      if (!world) {
        frame = requestAnimationFrame(animate);
        return;
      }
      const options = p.options || {};
      if (quality !== p.quality) {
        quality = p.quality;
        renderer.setPixelRatio(
          Math.min(
            window.devicePixelRatio || 1,
            quality === "high" ? 2 : quality === "low" ? 1 : 1.5
          )
        );
        resize();
        clouds.visible = quality !== "low";
        cities.visible = quality !== "low";
        stars.material.size = quality === "low" ? 0.6 : 0.85;
      }
      const moonPoint = toScene(moonPosition(world.time));
      moon.position.copy(moonPoint);
      planetEclipse.eclipseBody.value.copy(moonPoint);
      // Prescribed visual rotation; the orbital solver and drag use their own frame.
      planet.rotation.y = -0.45 + (world.time / 86164) * Math.PI * 2;
      cities.rotation.copy(planet.rotation);
      clouds.rotation.y = planet.rotation.y + world.time / 1400000;
      plane.visible = !!options.planes;
      const craftIds = new Set((world.crafts || []).map(craft => craft.id));
      craftMeshes.forEach((meshes, id) => {
        if (!craftIds.has(id)) {
          Object.values(meshes).forEach(mesh => {
            scene.remove(mesh);
            disposeObject(mesh);
          });
          craftMeshes.delete(id);
        }
      });
      const selected = (world.crafts || []).find(
        craft => craft.id === p.selectedId
      );
      (world.crafts || []).forEach(craft => {
        if (!craftMeshes.has(craft.id)) {
          const meshes = makeSpacecraft();
          [
            meshes.group,
            meshes.marker,
            meshes.velocity,
            meshes.gravity,
            meshes.trail
          ].forEach(mesh => scene.add(mesh));
          craftMeshes.set(craft.id, meshes);
        }
        const meshes = craftMeshes.get(craft.id),
          location = toScene(craft.position),
          visualSize = Math.max(
            0.008,
            Math.min(2.5, camera.position.distanceTo(location) * 0.007)
          );
        meshes.group.position.copy(location);
        meshes.group.scale.setScalar(visualSize);
        const velocity = new THREE.Vector3(...craft.velocity);
        const facing =
          craft.burning && craft.burnDirection
            ? new THREE.Vector3(
                ...(Array.isArray(craft.burnDirection)
                  ? craft.burnDirection
                  : directionVector(craft, craft.burnDirection, world))
              )
            : velocity.clone();
        if (facing.lengthSq() > 0)
          meshes.group.quaternion.setFromUnitVectors(
            new THREE.Vector3(0, 1, 0),
            facing.normalize()
          );
        velocity.normalize();
        meshes.group.visible = craft.status !== "crashed";
        meshes.plume.visible = !!craft.burning && craft.status === "active";
        meshes.plume.scale.y =
          Math.max(0.15, craft.burnThrottle || 1) *
          (reduced ? 1 : 0.96 + Math.sin(timestamp * 0.06) * 0.045);
        meshes.marker.position.copy(location);
        meshes.marker.quaternion.copy(camera.quaternion);
        meshes.marker.scale.setScalar(visualSize * 1.2);
        meshes.marker.visible =
          craft.id === p.selectedId && craft.status !== "crashed";
        meshes.velocity.position.copy(location);
        meshes.velocity.setDirection(
          velocity.lengthSq() > 0 ? velocity : new THREE.Vector3(0, 1, 0)
        );
        meshes.velocity.setLength(
          visualSize * 8,
          visualSize,
          visualSize * 0.45
        );
        meshes.velocity.visible =
          !!options.vectors && craft.status !== "crashed";
        meshes.gravity.position.copy(location);
        meshes.gravity.setDirection(
          new THREE.Vector3(
            ...gravityAcceleration(
              craft.position,
              world.time,
              world.perturbations
            )
          ).normalize()
        );
        meshes.gravity.setLength(visualSize * 6, visualSize, visualSize * 0.45);
        meshes.gravity.visible =
          !!options.gravity && craft.status !== "crashed";
        meshes.trail.visible = !!options.trails;
        if (timestamp - lastTrails > 140)
          replaceLine(meshes.trail, craft.trail);
      });
      if (timestamp - lastTrails > 140) lastTrails = timestamp;
      if (lastPaths !== p.paths || lastSelected !== p.selectedId) {
        lastPaths = p.paths;
        lastSelected = p.selectedId;
        replaceLine(currentLine, p.paths && p.paths.current);
        replaceLine(maneuverLine, p.paths && p.paths.maneuver);
      }
      currentLine.visible = !!options.predictions;
      maneuverLine.visible =
        !!options.predictions && !!(p.node && p.node.enabled);
      const nodePoint = p.paths && p.paths.nodePosition;
      nodeMarker.visible = !!(p.node && p.node.enabled && nodePoint);
      if (nodeMarker.visible) {
        nodeMarker.position.copy(toScene(positionOf(nodePoint)));
        nodeMarker.scale.setScalar(
          Math.max(
            0.012,
            camera.position.distanceTo(nodeMarker.position) * 0.009
          )
        );
        nodeMarker.rotation.z = reduced ? 0 : timestamp * 0.00018;
      }
      const mode = p.cameraMode || "planet",
        target = p.cameraTarget || "planet";
      const cameraRevision = p.cameraRevision || 0;
      if (
        mode !== lastMode ||
        target !== lastTarget ||
        cameraRevision !== lastCameraRevision ||
        (mode === "follow" && p.selectedId !== engine.followId)
      ) {
        let aim, eye;
        if (mode === "follow" && selected) {
          aim = toScene(selected.position);
          const center =
            aim.distanceTo(moonPoint) < MOON.sphereOfInfluence * SCALE
              ? moonPoint
              : new THREE.Vector3();
          const radial = aim.clone().sub(center).normalize();
          let tangent = new THREE.Vector3(
            ...directionVector(selected, "prograde", world)
          );
          tangent.addScaledVector(radial, -tangent.dot(radial));
          if (tangent.lengthSq() < 0.001)
            tangent = new THREE.Vector3(0, 0, 1).cross(radial);
          if (tangent.lengthSq() < 0.001)
            tangent = new THREE.Vector3(1, 0, 0).cross(radial);
          tangent.normalize();
          const normal = radial.clone().cross(tangent).normalize();
          eye = aim
            .clone()
            .addScaledVector(radial, 2.4)
            .addScaledVector(tangent, -1.8)
            .addScaledVector(normal, 0.8);
          previousFollow = aim.clone();
        } else if (mode === "planet") {
          aim = target === "moon" ? moonPoint.clone() : new THREE.Vector3();
          eye = aim
            .clone()
            .add(
              target === "moon"
                ? new THREE.Vector3(7, -10, 5)
                : new THREE.Vector3(16, -23, 13)
            );
          previousFollow = null;
        } else previousFollow = null;
        if (aim)
          tween = {
            fromTarget: controls.target.clone(),
            fromEye: camera.position.clone(),
            aim,
            eye,
            start: timestamp,
            duration: reduced ? 0 : 1050
          };
        else tween = null;
        lastMode = mode;
        lastTarget = target;
        lastCameraRevision = cameraRevision;
        engine.followId = p.selectedId;
      }
      if (tween) {
        const t = tween.duration
            ? Math.min(1, (timestamp - tween.start) / tween.duration)
            : 1,
          ease = t * t * (3 - 2 * t);
        if (mode === "follow" && selected) {
          const now = toScene(selected.position),
            delta = now.clone().sub(tween.aim);
          tween.aim.copy(now);
          tween.eye.add(delta);
        }
        controls.target.lerpVectors(tween.fromTarget, tween.aim, ease);
        camera.position.lerpVectors(tween.fromEye, tween.eye, ease);
        if (t === 1) {
          tween = null;
          previousFollow =
            mode === "follow" && selected ? toScene(selected.position) : null;
        }
      } else if (mode === "follow" && selected) {
        const now = toScene(selected.position);
        if (previousFollow)
          camera.position.add(now.clone().sub(previousFollow));
        controls.target.copy(now);
        previousFollow = now;
      } else if (mode === "planet" && target === "moon") {
        camera.position.add(moonPoint.clone().sub(controls.target));
        controls.target.copy(moonPoint);
      }
      controls.update();
      if (mode === "follow") {
        // Follow-camera framing and transitions stay outside both solid bodies.
        [
          {center: new THREE.Vector3(), radius: PLANET.radius * SCALE},
          {center: moonPoint, radius: MOON.radius * SCALE}
        ].forEach(body => {
          const offset = camera.position.clone().sub(body.center),
            clearance = body.radius + 0.03;
          if (offset.length() < clearance) {
            if (offset.lengthSq() < 1e-12) offset.copy(NORTH);
            camera.position.copy(body.center).add(offset.setLength(clearance));
          }
        });
        camera.lookAt(controls.target);
      }
      // Keep depth precision near the camera instead of using one near plane across
      // spacecraft, planetary, and system scales. This prevents cloud/city flicker.
      const near = Math.max(
        0.000001,
        Math.min(0.25, camera.position.distanceTo(controls.target) * 0.002)
      );
      if (Math.abs(camera.near - near) > near * 0.08) {
        camera.near = near;
        camera.updateProjectionMatrix();
      }
      renderer.render(scene, camera);
      if (timestamp - lastLabels > 150) {
        const next = [];
        if (options.labels !== false) {
          const globeLabel = projected(
            new THREE.Vector3(0, 0, PLANET.radius * SCALE * 1.05)
          );
          if (globeLabel)
            next.push({
              ...globeLabel,
              id: "planet",
              text: PLANET.name,
              type: "body"
            });
          const satelliteLabel = projected(
            moonPoint
              .clone()
              .add(new THREE.Vector3(0, 0, MOON.radius * SCALE * 1.4))
          );
          if (satelliteLabel)
            next.push({
              ...satelliteLabel,
              id: "moon",
              text: MOON.name,
              type: "body"
            });
          (world.crafts || []).forEach(craft => {
            const location = toScene(craft.position),
              label = projected(location);
            // A ray behind the solid planetary body should not leave a floating ship label.
            const sight = new THREE.Ray(
              camera.position,
              location.clone().sub(camera.position).normalize()
            );
            const obstruction = sight.intersectSphere(
              new THREE.Sphere(new THREE.Vector3(), PLANET.radius * SCALE),
              new THREE.Vector3()
            );
            const hidden =
              obstruction &&
              obstruction.distanceTo(camera.position) + 0.005 <
                location.distanceTo(camera.position);
            if (label && !hidden)
              next.push({
                ...label,
                id: craft.id,
                text: craft.name,
                type: "craft",
                selected: craft.id === p.selectedId,
                status: craft.status
              });
          });
          if (nodeMarker.visible) {
            const markerLabel = projected(nodeMarker.position);
            if (markerLabel)
              next.push({
                ...markerLabel,
                id: "node",
                text: movingNode ? "Release to set burn" : "Drag to move burn",
                type: "node"
              });
          }
        }
        setLabels(next);
        lastLabels = timestamp;
      }
      frame = requestAnimationFrame(animate);
    };
    frame = requestAnimationFrame(animate);
    setReady(true);
    return () => {
      disposed = true;
      cancelAnimationFrame(frame);
      if (observer) observer.disconnect();
      window.removeEventListener("resize", resize);
      renderer.domElement.removeEventListener(
        "pointerdown",
        onPointerDown,
        true
      );
      renderer.domElement.removeEventListener("pointermove", nodeMove, true);
      renderer.domElement.removeEventListener("pointerup", onPointerUp, true);
      renderer.domElement.removeEventListener("pointercancel", onPointerCancel);
      renderer.domElement.removeEventListener(
        "webglcontextlost",
        onContextLost
      );
      renderer.domElement.removeEventListener("keydown", onKey);
      controls.dispose();
      disposeObject(scene);
      [
        map,
        specularMap,
        cityMap,
        cloudMap,
        moonMap,
        sunGlow.material.map
      ].forEach(texture => texture.dispose());
      renderer.dispose();
      if (host.contains(renderer.domElement))
        host.removeChild(renderer.domElement);
      engineRef.current = null;
    };
  }, []);

  return (
    <div
      className={"orbit-scene" + (draggingNode ? " orbit-scene-node-drag" : "")}
      ref={hostRef}
    >
      {!ready && (
        <div className="orbit-scene-loading">Preparing the observatory…</div>
      )}
      <div className="orbit-scene-labels" aria-label="Visible objects">
        {labels.map(label =>
          label.type === "craft" ? (
            <button
              key={label.id}
              type="button"
              style={{left: label.x, top: label.y}}
              className={
                "orbit-object-label orbit-craft-label" +
                (label.selected ? " is-selected" : "")
              }
              onClick={() => props.onSelect && props.onSelect(label.id)}
              aria-label={"Select " + label.text}
            >
              <i />
              <span>{label.text}</span>
              {label.status === "crashed" && <small>IMPACT</small>}
            </button>
          ) : (
            <span
              key={label.id}
              style={{left: label.x, top: label.y}}
              className={"orbit-object-label orbit-" + label.type + "-label"}
            >
              {label.text}
            </span>
          )
        )}
      </div>
      <div className="orbit-scene-coordinate" aria-hidden="true">
        <i /> INERTIAL FRAME <span>+Z NORTH</span>
      </div>
      <div className="orbit-scene-instructions">
        <span>DRAG TO EXPLORE</span>
        <b>·</b>
        <span>SCROLL / PINCH TO ZOOM</span>
        <b>·</b>
        <span>CLICK A SPACECRAFT</span>
      </div>
    </div>
  );
}
